INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "罗弘信", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257文德元年条所见人物：罗弘信。", "biography": null, "status": "draft", "id": "da48e163-21a8-54a2-a3a0-cdef2344d96a"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "孔纬", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：孔纬。", "biography": null, "status": "draft", "id": "07254f47-15dc-55d0-b38f-bfefa4def94e"}, {"name": "张浚", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：张浚。", "biography": null, "status": "draft", "id": "0ab7d6a4-deb7-5601-86cd-77e4e2b19fc2"}, {"name": "崔昭纬", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：崔昭纬。", "biography": null, "status": "draft", "id": "99370461-a1dd-57da-a64e-c76fb6ea7ba7"}, {"name": "徐彦若", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：徐彦若。", "biography": null, "status": "draft", "id": "bdcb2b2c-637f-5dfc-bfa9-bcd06621907d"}, {"name": "崔慎由", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：崔慎由。", "biography": null, "status": "draft", "id": "8affad68-f521-5797-9836-653550779fa7"}, {"name": "徐商", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：徐商。", "biography": null, "status": "draft", "id": "d393b580-b61b-5a35-aa47-efd3248009d9"}, {"name": "杨复恭", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：杨复恭。", "biography": null, "status": "draft", "id": "d84e65f4-4bf5-58ad-a8c6-d69729edbc51"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "孙儒", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：孙儒。", "biography": null, "status": "draft", "id": "4426793f-0bd8-5a79-919f-7e3a0ddae520"}, {"name": "田頵", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的田頵，在此段中为击退进攻者。", "biography": null, "status": "draft", "id": "c59b24ec-67c0-5ac6-aaaf-4908d96913b9"}, {"name": "安仁义", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：安仁义。", "biography": null, "status": "draft", "id": "818f8166-7d71-5f56-8c1b-a53a37fca14f"}, {"name": "杨行密", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：杨行密。", "biography": null, "status": "draft", "id": "ad75628e-5958-5672-9403-eb349ca77e6e"}, {"name": "李从立", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：李从立。", "biography": null, "status": "draft", "id": "69d5fb4f-a258-5972-a137-168fb3ab5047"}, {"name": "台濛", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：台濛。", "biography": null, "status": "draft", "id": "7de43550-c1ce-51b9-bf23-dc637131efc5"}, {"name": "李神福", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的李神福，在此段中为用疑兵解围者。", "biography": null, "status": "draft", "id": "61a41119-a9f8-5beb-8356-77ed00b4ae34"}, {"name": "李罕之", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：李罕之。", "biography": null, "status": "draft", "id": "3a3944bf-1d15-5b41-8fde-e3f51fbe285c"}, {"name": "韦昭度", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：韦昭度。", "biography": null, "status": "draft", "id": "4d186310-6106-56bc-9a34-fa1d5d5d7894"}, {"name": "陈敬瑄", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的陈敬瑄：此前许诺以东川酬赏高仁厚。", "biography": null, "status": "draft", "id": "ad1f9c74-f6fd-50ff-b6c3-679c0c591a71"}, {"name": "顾彦朗", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启三年条所见人物：顾彦朗。", "biography": null, "status": "draft", "id": "f94b234c-1029-562a-8d41-de3e70fa7892"}, {"name": "王建", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“蜀王与晋王讨论讨梁及称帝”中为致书提议者。", "biography": null, "status": "draft", "id": "b02193d6-1c17-5154-bb7c-3295ed8dbbec"}, {"name": "王师范", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258龙纪元年条所见人物：王师范。", "biography": null, "status": "draft", "id": "85e4cc92-ce18-53c7-9bab-49ca198da0c3"}, {"name": "卢弘", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：卢弘。", "biography": null, "status": "draft", "id": "87ace4bf-877e-5585-99d1-c86bbff878f0"}, {"name": "张蟾", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258龙纪元年条所见人物：张蟾。", "biography": null, "status": "draft", "id": "a853bd69-e42a-5739-a12a-cec0913ed7d6"}, {"name": "刘鄩", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：刘鄩。", "biography": null, "status": "draft", "id": "8d51da07-a3ec-5947-936c-26ce986ed6fb"}, {"name": "崔安潜", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：崔安潜。", "biography": null, "status": "draft", "id": "500c310b-03c2-59e0-bd61-2cbd4c3588da"}, {"name": "韩建", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“韩建出任司徒、同平章事”中为受任者。", "biography": null, "status": "draft", "id": "0a022fc7-47b3-5530-98ad-3625fceab9a5"}, {"name": "安知建", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：安知建。", "biography": null, "status": "draft", "id": "c875ff28-a497-54ae-bfc4-d2a7620f29eb"}, {"name": "李存孝", "aliases": ["安敬思"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的李存孝，在此段中为李克用养子。", "biography": null, "status": "draft", "id": "d25efb4e-74a3-5bab-b1e4-a79cee0716c3"}, {"name": "朱瑄", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：朱瑄。", "biography": null, "status": "draft", "id": "dcaf5869-c45e-5845-b02f-6418dd1f22eb"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱全忠内黄击罗弘信至永定桥", "start_year": 891, "end_year": 891, "time_original": "891年正月丙辰", "dynasty": "唐", "description": "罗弘信驻军内黄，朱全忠进击，《通鉴》记五战皆捷，推进至永定桥，斩首万余。", "phases": [], "location_name": "内黄、永定桥", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1cc8ece7-bb54-53ab-b3f3-68dbdcf51090"}, {"title": "罗弘信求和，朱全忠止掠还俘", "start_year": 891, "end_year": 891, "time_original": "891年正月丙辰战后", "dynasty": "唐", "description": "罗弘信遣使以厚币求和，朱全忠令停止焚掠、归还俘虏，回军河上；《通鉴》称魏博自此服于汴。", "phases": [], "location_name": "魏博、河上", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2d4f80c5-442a-5dc6-a3a1-d82b0b69595a"}, {"title": "孔纬张浚罢相转外任", "start_year": 891, "end_year": 891, "time_original": "891年正月庚申", "dynasty": "唐", "description": "朝廷以孔纬为荆南节度使，以张浚为鄂岳观察使。", "phases": [], "location_name": "荆南、鄂岳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "da38c5d3-75f6-55af-8e76-8ccca9b663b5"}, {"title": "崔昭纬徐彦若拜相", "start_year": 891, "end_year": 891, "time_original": "891年正月庚申条", "dynasty": "唐", "description": "朝廷以翰林学士承旨、兵部侍郎崔昭纬同平章事，以御史中丞徐彦若为户部侍郎、同平章事。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "b9454949-a3ea-5d6c-828f-e42006897ad1"}, {"title": "杨复恭使人劫孔纬长乐坡", "start_year": 891, "end_year": 891, "time_original": "891年正月庚申条后", "dynasty": "唐", "description": "杨复恭遣人劫孔纬，斩其旌节，夺尽资装，孔纬仅自脱免。", "phases": [], "location_name": "长乐坡", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bf432f19-1edf-5237-9969-f1a9913890cf"}, {"title": "李克用再上表指责张浚", "start_year": 891, "end_year": 891, "time_original": "891年正月条；具体日未载", "dynasty": "唐", "description": "李克用遣使再上表，指责张浚求一时之功、与朱温连结，称自己无官爵、不敢归藩方，欲寄寓河中待命。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "b56186cf-e3c4-5a2f-988e-7c06c22f7457"}, {"title": "孔纬张浚再贬，李克用复官爵", "start_year": 891, "end_year": 891, "time_original": "891年正月条；再奏后", "dynasty": "唐", "description": "朝廷再贬孔纬为均州刺史、张浚为连州刺史，恢复李克用全部官爵，令其归晋阳。", "phases": [], "location_name": "均州、连州、晋阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "dedf6823-58d6-519f-a897-6361bf4aa8ed"}, {"title": "孙儒尽举淮蔡军渡江南攻", "start_year": 891, "end_year": 891, "time_original": "891年正月癸酉条", "dynasty": "唐", "description": "孙儒尽举淮、蔡军渡江，自润州转战向南，田頵、安仁义屡败退，杨行密所属城戍相继奔溃。", "phases": [], "location_name": "江、润州以南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b46471f8-3edf-5dde-a919-5c78baa0daa7"}, {"title": "台濛传呼疑兵退李从立", "start_year": 891, "end_year": 891, "time_original": "891年正月癸酉条后", "dynasty": "唐", "description": "李从立突然到宣州东溪，杨行密守备未固，夜遣合肥台濛驻溪西。台濛令士卒往返传呼，李从立以为大军续至，撤离。", "phases": [], "location_name": "宣州东溪、溪西", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9d7bd364-35d6-54cf-a3d6-0f8617f281c6"}, {"title": "李神福溧水佯退夜袭孙儒军", "start_year": 891, "end_year": 891, "time_original": "891年正月条；具体日未载", "dynasty": "唐", "description": "孙儒前军至溧水，杨行密遣李神福抵抗；李神福佯退示怯，敌军不设防，夜率精兵袭击，书载俘斩千人。", "phases": [], "location_name": "溧水", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a0620eb1-d121-5637-8a86-33bf615fa7d1"}, {"title": "李克用加守中书令，李罕之复官爵", "start_year": 891, "end_year": 891, "time_original": "891年二月", "dynasty": "唐", "description": "朝廷加李克用守中书令，恢复李罕之官爵。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "f795d974-2c50-5d40-a269-66125f646ce3"}, {"title": "张浚再贬绣州司户", "start_year": 891, "end_year": 891, "time_original": "891年二月", "dynasty": "唐", "description": "朝廷再次贬张浚为绣州司户。", "phases": [], "location_name": "绣州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a461a327-289e-5019-8d2c-110a0d07038e"}, {"title": "韦昭度讨西川三年未克，朝议息兵", "start_year": null, "end_year": null, "time_original": "讨西川以来三年；逐事确年未载", "dynasty": "唐", "description": "《通鉴》述韦昭度统诸道军讨陈敬瑄，三年未能攻克，馈运不继，朝议欲停战。", "phases": [], "location_name": "西川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0876e90f-848b-5743-ab76-f8bc7e019068"}, {"title": "陈敬瑄复官爵，顾彦朗王建奉令归镇", "start_year": 891, "end_year": 891, "time_original": "891年三月乙亥", "dynasty": "唐", "description": "朝廷恢复陈敬瑄官爵，命顾彦朗、王建各率军归镇。", "phases": [], "location_name": "西川及原镇", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "29343ee5-ec04-56b1-8e01-6e629ba74781"}, {"title": "卢弘受命攻棣州却回攻王师范", "start_year": 891, "end_year": 891, "time_original": "891年三月后条；具体日未载", "dynasty": "唐", "description": "王师范遣都指挥使卢弘攻棣州张蟾，卢弘却率军返回攻王师范；王师范以重赂迎接，表示愿让位保全性命，卢弘因其年少而不防备。", "phases": [], "location_name": "棣州、平卢", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "93a9ae9b-5a06-5291-9ae1-994ba61ace6c"}, {"title": "王师范设宴，刘鄩杀卢弘", "start_year": 891, "end_year": 891, "time_original": "891年三月后条；卢弘入城后", "dynasty": "唐", "description": "王师范密令安丘小校刘鄩杀卢弘，卢弘入城后，王师范伏甲设宴，刘鄩在座上杀卢弘及其党数人。", "phases": [], "location_name": "平卢城中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8b9c2936-9106-5087-a81c-488d84898bfc"}, {"title": "王师范攻棣州斩张蟾，崔安潜归京", "start_year": 891, "end_year": 891, "time_original": "891年三月后条；卢弘死后", "dynasty": "唐", "description": "王师范慰谕赏赐士卒，亲率攻棣州，拘执张蟾并斩之；崔安潜逃归京师。", "phases": [], "location_name": "棣州、京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7f05d68d-ec37-552b-bebb-4a4ce9974653"}, {"title": "王师范获平卢节度使，刘鄩获副职", "start_year": 891, "end_year": 891, "time_original": "891年三月后条；平卢争位结束后", "dynasty": "唐", "description": "王师范任刘鄩为马步副都指挥使，朝廷诏以王师范为平卢节度使。", "phases": [], "location_name": "平卢", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ce260b8e-0fec-56c5-bc72-a3201ca1825b"}, {"title": "王师范拜本县令的书载逸事", "start_year": null, "end_year": null, "time_original": "本县令到任时；具体年日未载", "dynasty": "唐", "description": "《通鉴》述王师范每逢本县令到官，备仪卫谒见，自称百姓王师范拜于庭；僚佐劝谏时解释为敬桑梓、教子孙不忘本。", "phases": [], "location_name": "本县", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "59e9a70e-1b5c-5198-86f0-a20e710ba802"}, {"title": "张浚孔纬依韩建，朱全忠代诉获自便", "start_year": 891, "end_year": 891, "time_original": "891年三月后条；具体日未载", "dynasty": "唐", "description": "张浚至蓝田后逃依华州韩建，与孔纬密向朱全忠求救。朱全忠为二人上表申冤，朝廷允其自便；孔纬至商州而返，亦寓华州。", "phases": [], "location_name": "蓝田、华州、商州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1ce0803e-00b3-56ab-9c0d-ac1dbd6f8c09"}, {"title": "安知建通汴，李克用表李存孝代任", "start_year": 891, "end_year": 891, "time_original": "891年三月后条；具体日未载", "dynasty": "唐", "description": "邢洺节度使安知建秘密联系朱全忠，李克用上表请李存孝代之，安知建害怕逃至青州，朝廷任其为神武统军。", "phases": [], "location_name": "邢洺、青州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3cacd7e3-b951-59de-9ebc-92a27fc6bc3e"}, {"title": "朱瑄伏杀赴京安知建，传首晋阳", "start_year": 891, "end_year": 891, "time_original": "891年三月后条；神武统军任命后", "dynasty": "唐", "description": "安知建率部欲赴京师，途经郓州；朱瑄与李克用正友好，在河上伏杀安知建，将首级送晋阳。", "phases": [], "location_name": "郓州、河上、晋阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7096de0e-6c57-54e8-9f00-c4386f879f71"}, {"title": "彗星见三台东入太微", "start_year": 891, "end_year": 891, "time_original": "891年四月", "dynasty": "唐", "description": "《通鉴》记彗星出现于三台，向东进入太微，长十丈余。", "phases": [], "location_name": "三台、太微", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8c474d0a-7f57-55e0-ba68-73ca4fd27faa"}, {"title": "朝廷四月甲申赦天下", "start_year": 891, "end_year": 891, "time_original": "891年四月甲申", "dynasty": "唐", "description": "朝廷赦天下。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "fcfd7806-674d-5705-a0fc-39a4d25cae18"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

